import AVFoundation
import Foundation
let engine = AVAudioEngine(), player = AVAudioPlayerNode(), pitch = AVAudioUnitTimePitch()
engine.attach(player); engine.attach(pitch)
let format = AVAudioFormat(standardFormatWithSampleRate: 48_000, channels: 2)!
engine.connect(player, to: pitch, format: format)
engine.connect(pitch, to: engine.mainMixerNode, format: format)
let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: 96_000)!
buffer.frameLength = 96_000
for channel in 0..<2 { memset(buffer.floatChannelData![channel], 0, 96_000 * MemoryLayout<Float>.size) }
player.volume = 0
player.scheduleBuffer(buffer)
try engine.start(); player.play()
for _ in 0..<10 {
 Thread.sleep(forTimeInterval: 0.05)
 let before = ProcessInfo.processInfo.systemUptime
 if let node = player.lastRenderTime, let time = player.playerTime(forNodeTime: node) {
  let after = ProcessInfo.processInfo.systemUptime
  let row: [String: Any] = ["before":before,"after":after,"nodeHostValid":node.isHostTimeValid,"playerHostValid":time.isHostTimeValid,"nodeSample":node.sampleTime,"playerSample":time.sampleTime,"sampleRate":time.sampleRate,"nodeHostSeconds":AVAudioTime.seconds(forHostTime: node.hostTime),"playerHostSeconds":AVAudioTime.seconds(forHostTime: time.hostTime)]
  print(String(data: try JSONSerialization.data(withJSONObject: row, options: [.sortedKeys]), encoding:.utf8)!)
 }
}
player.stop(); engine.stop()
